window.debounce=(t,s)=>{let e;return(...i)=>{clearTimeout(e),e=setTimeout(()=>{t.apply(this,i)},s)}},window.TextSplitter=class{constructor(t,s={}){this.element=t,this.options=s,this.init()}init(){this.splitInstance=new SplitType(this.element,{types:this.options.splitTypeTypes||"words, chars"})}getChars(){return this.splitInstance?this.splitInstance.chars:[]}getWords(){return this.splitInstance?this.splitInstance.words:[]}revert(){this.splitInstance&&this.splitInstance.revert()}};